function sound(kind='move',delay=0){if(!audioContext||audioContext.state!=='running')return;try{const t=audioContext.currentTime+delay;const note=(hz,start,length,volume,type='sine')=>{const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.type=type;oscillator.frequency.setValueAtTime(hz,start);gain.gain.setValueAtTime(volume,start);gain.gain.exponentialRampToValueAtTime(.001,start+length);oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start(start);oscillator.stop(start+length)};if(kind==='invalid'){note(160,t,.16,.08,'sawtooth')}else if(kind==='win'){note(100,t,.25,.22);[523,659,784,1047].forEach((hz,i)=>note(hz,t+.08+i*.10,.3,.10,'triangle'))}else if(kind==='end'){note(440,t,.18,.08);note(330,t+.12,.25,.08)}else{note(650,t,.035,.10,'triangle');note(180,t,.06,.16)}}catch{}}
function gameSounds(record,arena=false){if(!record)return;const previous=heardGames.get(record),count=record.moves.length;heardGames.set(record,{count,result:record.result});if(!previous)return;for(let i=0;i<Math.min(2,Math.max(0,count-previous.count));i++)sound('move',i*.07);if(record.result&&!previous.result)sound(record.result==='win'||arena&&record.winner?'win':'end',.12)}
