function setupPage(first){const p=state.profile||{},known=p.currentRating!=null||currentRating()!=null;return `<div class="setup"><div class="intro"><div class="eyebrow">${first?'A BETTER WAY TO PRACTICE':'YOUR TRAINING PLAN'}</div><h1 style="margin-top:13px">${first?'Start where you are.':'Make this your training room.'}</h1><p>${first?'Tell us a little about your chess. We’ll find the right challenge together.':'Your game rating and puzzle difficulty are separate. Your solves guide the training.'}</p></div><form id="profile-form" class="panel"><h2>${first?'First, your starting point':'Your rating & goal'}</h2><p class="fine">An Elo is a chess rating. It’s completely fine if you don’t have one yet.</p><div class="setup-choices"><label class="choice"><input type="radio" name="known" value="yes" ${known?'checked':''}>I know my rating</label><label class="choice"><input type="radio" name="known" value="no" ${known?'':'checked'}>I don’t know my rating</label></div><div class="form-grid"><label class="form-field">Current game rating<input id="current-rating" name="current" type="number" min="100" max="3500" step="1" value="${known?currentRating():''}" placeholder="For example, 950" ${known?'required':'disabled'}><small>Use a rapid rating from the platform you play on.</small></label><label class="form-field">The rating I’m working toward<input name="goal" type="number" min="100" max="3500" step="1" value="${p.goal||1500}" required><small>A direction to work toward, without a deadline.</small></label><label class="form-field full">Chess platform / time control<input name="platform" value="${esc(p.platform||'')}" placeholder="For example, Chess.com rapid"><small>Optional. Keep rating updates comparable.</small></label></div>${!first?'<label class="inline-check section-space"><input type="checkbox" name="recalibrate">Start a fresh difficulty calibration from this rating</label><p class="fine muted">Your journal and used positions will be kept.</p>':''}<button class="button primary">${first?'Create my training plan':'Save training plan'}</button><p class="fine muted" style="margin:14px 0 0;text-align:center">${known?'We’ll start near your level and adjust with each puzzle.':'No rating? We start easy. Fast, accurate solves bring harder puzzles.'}</p></form>${first?'<div class="setup-benefits"><div><b>Real positions</b>Rated puzzles from real games.</div><div><b>Your pace</b>Difficulty follows your answers.</div><div><b>Fresh practice</b>No automatic position repeats.</div></div>':`<details class="panel section-space"><summary>Backups & help</summary><div hidden><h2>How your coach adjusts</h2><p class="fine">A clean solve means no incorrect moves, hints, or solution reveals. Two or more quick, clean solves raise difficulty more quickly. A thoughtful solve keeps the challenge manageable. Mistakes hold the level steady; repeated struggles bring a small step down.</p><p class="fine">Time is measured while the training room is visible and unpaused. Longer lines get more thinking time. Puzzle ratings are training difficulty, not an estimate of your game rating.</p><p class="fine">There are ${fmt(bank.length)} real positions. New sessions avoid both used IDs and used board positions. If a skill runs out, the app asks you to choose another skill.</p></div><div class="row wrap"><button class="button secondary" type="button" data-export>Export my backup</button><label class="button secondary" style="cursor:pointer">Restore a backup<input type="file" class="restore-file" accept="application/json" hidden></label></div><p class="fine muted" style="margin:15px 0 0">Your records live in this browser. Export a backup to move them to another device.</p></details>`}</div>`}
function chart(){let start=state.profile?.startRating,rows=[...(start!=null&&state.ratings[0]?.value!==start?[{value:start,date:'Starting point'}]:[]),...state.ratings];if(!rows.length)return '<div class="empty" style="padding:25px 10px"><p>No game rating yet. Your first update will start this chart.</p><button class="button secondary small" data-goto="progress">Record a rating</button></div>';let goal=state.profile?.goal||1500,low=Math.min(...rows.map(r=>r.value),goal)-100,high=Math.max(...rows.map(r=>r.value),goal)+100;let y=v=>165-(v-low)/(high-low)*140,xy=rows.map((r,i)=>[24+i*640/Math.max(1,rows.length-1),y(r.value)]);return `<svg class="chart" viewBox="0 0 750 195" role="img" aria-label="Game rating history: ${rows.map(r=>r.value).join(', ')}. Goal ${goal}."><line x1="24" x2="690" y1="${y(goal)}" y2="${y(goal)}" stroke="#ccd9bf" stroke-dasharray="5 6"/><text x="700" y="${y(goal)+4}" fill="#8b9b7d" font-size="11">${goal}</text><polyline points="${xy.map(x=>x.join(',')).join(' ')}" fill="none" stroke="#74945b" stroke-width="3"/>${xy.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="#2c5c43"><title>${esc(rows[i].date)}: ${rows[i].value}</title></circle>`).join('')}</svg><div class="chart-labels"><span>${fmt(rows[0].value)} · ${rows[0].date==='Starting point'?'starting point':esc(rows[0].date)}</span><span>${fmt(rows.at(-1).value)} · latest</span></div>`}
function dashboardPage(){const checks=state.checks[weekKey()]||{};return `<div class="simple-home"><div class="eyebrow">CHESS, DAILY</div><h1>Your chess checklist.</h1><p>Choose one thing. We’ll take it from here.</p><div class="simple-rating">${currentRating()==null?'No rating needed':fmt(currentRating())+' rating'} <span>Goal ${fmt(state.profile.goal)}</span><button class="text-button" data-goto="settings">Change</button></div><div class="panel simple-list">${tasks.map((t,i)=>`<div class="simple-task"><label><input type="checkbox" data-task="${t[0]}" ${checks[t[0]]?'checked':''}><b>${t[1]}</b></label>${i===0?`<button class="button primary" id="quick-puzzles">${state.active?'Continue puzzles':'Play puzzles'}</button>`:`${i===1?'<button class="button secondary" data-goto="game">Play computer</button>':`<button class="button secondary" data-goto="${i===2?'games':i===3?'learn':'endgames'}">${i===2?'Review games':i===3?'Learn a skill':'Practice endgames'}</button>`}`}</div>`).join('')}</div></div>`}
function trainingPage(){if(state.active)return activePage();let skill=selectedSkill||recommendSkill(state),c=trainingCoach(),p=chooseTrainingPuzzle(skill),lesson=p?lessonFor(state,skill,p):null;return `<div class="training-start"><div class="intro"><div class="eyebrow">YOUR NEXT TEN MINUTES</div><h1 style="margin-top:10px">Train at your edge.</h1><p>Pick one skill. Solve three real positions. Leave with one useful idea.</p></div><div class="skill-picker">${Object.entries(SKILLS).map(([k,s])=>`<button class="skill-choice ${skill===k?'active':''}" data-skill="${k}" aria-pressed="${skill===k}"><span>${k==='forks'?'<img class="knight-icon" src="pieces/bN.svg" alt="">':s.icon}</span><b>${s.name}</b><small>${s.description}</small>${k===recommendSkill(state)?'<div class="badge" style="margin-top:10px">Recommended</div>':''}</button>`).join('')}</div><div class="panel"><div class="row wrap"><div><div class="eyebrow">TODAY’S FOCUS · ${SKILLS[skill].name.toUpperCase()}</div><h2 style="margin-top:12px">${lesson?esc(lesson.title):'You’ve used every position in this skill.'}</h2></div><span class="badge">Difficulty target ${fmt(c.target)}</span></div><p>${lesson?esc(lesson.body):'Choose another skill for fresh positions. We won’t automatically repeat a board you’ve seen.'}</p><div class="instruction"><b>Your pace sets the challenge.</b> ${esc(c.reason)} ${p&&Math.abs(p.rating-c.target)>175?'The closest fresh puzzle in this skill is rated '+p.rating+'.':''}</div><button id="begin-session" class="button primary" ${p?'':'disabled'}>Start my session</button><p class="fine muted" style="margin:15px 0 0">2 minutes: learn the idea · 6 minutes: puzzles · 2 minutes: reflect<br>Click a piece, then its destination. Your opponent’s replies play automatically.</p></div></div>`}
function beginSession(){let skill=selectedSkill||recommendSkill(state),p=chooseTrainingPuzzle(skill);if(!p)return toast('No fresh puzzles remain in this skill. Choose another.');let lesson=lessonFor(state,skill,p);state.active={id:Date.now(),version:2,date:localDate(),skill,lessonId:lesson.id,lessonTitle:lesson.title,lessonBody:lesson.body,seconds:0,results:[],puzzle:null,mistakes:'',tip:SKILLS[skill].tip,targetStart:trainingCoach().target,stage:'puzzles'};newPuzzle(p);paused=false;lastTick=Date.now();save();render()}
function newPuzzle(preselected){const d=state.active,p=preselected||chooseTrainingPuzzle(d.skill);if(!p){d.stage='notes';save();toast('No fresh positions remain for this skill. Save your session, then choose another.');return}state.seen.push(p.id);state.seenPositions.push(positionKey(p.fen));d.puzzle={id:p.id,cursor:0,seconds:0,mistakes:[],hints:0,done:false,revealed:false,moves:[],targetBefore:trainingCoach().target};selectedSquare=null;replayStep=null;feedback=null;save()}
