function ensurePuzzleAdvance(){const done=view==='training'&&state.active?.stage==='puzzles'&&state.active.puzzle?.done;if(!done){stopPuzzleAdvance();return}if(puzzleAdvanceTimer||paused)return;if(puzzleDelaySeconds===0){puzzleAdvanceTimer=setTimeout(advancePuzzle,0);return}puzzleAdvanceCount=puzzleDelaySeconds;puzzleAdvanceTimer=setInterval(()=>{if(view!=='training'||!state.active?.puzzle?.done){stopPuzzleAdvance();return}if(paused)return;if(puzzleAdvanceCount<=1){advancePuzzle();return}puzzleAdvanceCount--;render()},1000)}
function activeGame(){const p=state.active?.puzzle;if(!p)return null;const data=puzzleMap.get(p.id),game=new Chess(data.fen);const line=p.solution||(p.alternative?[p.alternative]:data.moves);const limit=p.done?(replayStep??line.length):p.cursor;for(const m of line.slice(0,limit))game.move(uci(m));if(p.preview&&!p.done)game.move(p.preview);return game}
