const eloLabels={1:' · ~500 Elo',2:' · ~700 Elo',3:' · ~1,000 Elo',4:' · ~1,800 Elo',5:' · Elo hidden',8:' · Automatically adjusts to your level'};function botOptions(control,selected){return Object.entries(LEVELS).filter(([k])=>!['6','7'].includes(k)||hyperAllowed(control)).map(([k,l])=>`<option value="${k}" ${String(k)===String(selected)?'selected':''}>${l.name}${eloLabels[k]||''}</option>`).join('')}function refreshBotSelect(select,control){if(!select)return;const wanted=select.value,allowed=Object.keys(LEVELS).filter(k=>!['6','7'].includes(k)||hyperAllowed(control)),next=allowed.includes(wanted)?wanted:allowed.at(-1);select.innerHTML=botOptions(control,next);updateBotPicker(select)}
