function gamesPage(){
  const games=state.games||[];
  if(reviewGameIndex==null||!games[reviewGameIndex])return `<div class="simple-home"><div class="eyebrow">LEARN FROM YOUR OWN MOVES</div><h1>Game review.</h1><p>Replay a game and follow the evaluation bar as the position changes.</p>${games.length?games.map((g,i)=>`<div class="panel section-space row wrap"><div><b>${g.kind==='endgame'?'Endgame':'Computer game'} · ${esc(g.date)}</b><p class="fine">${g.result==='ended'?'Unfinished':g.result} · ${g.moves.length} half-moves · ${LEVELS[g.level]?.name||'Little Fish'} · ${controlInfo(g.control)?.name||'Untimed'}</p></div><button class="button secondary" data-open-game="${i}">Review game ${i+1}</button></div>`).reverse().join(''):'<div class="panel"><p>Your games will appear here automatically.</p><button class="button primary" data-goto="game">Play your first game</button></div>'}</div>`;
  const g=games[reviewGameIndex],summary=gameSummary(g);
  gameStep=clamp(gameStep,0,g.moves.length);
  const c=gameFrom(g,gameStep),r=summary.rows[gameStep-1],analysis=g.analysis?.[gameStep-1]?.reviewVersion===3?g.analysis[gameStep-1]:null;
  let previousIndex=-1;
  for(let i=gameStep-2;i>=0;i--)if(g.analysis?.[i]?.reviewVersion===3){previousIndex=i;break}
  const previousAnalysis=previousIndex>=0?g.analysis[previousIndex]:null;
  const previousColor=previousIndex>=0?summary.rows[previousIndex].color:'w';
  const shownAnalysis=analysis||previousAnalysis;
  const shownColor=analysis?r?.color:previousColor;
  const ev=gameStep===0?evaluation({engine:'search',actualScore:0,actualMate:null},'w'):evaluation(shownAnalysis,shownColor);
  return `<div class="review-room"><div class="row wrap"><button class="button secondary" id="all-games">All games</button><h2>Move ${gameStep} of ${g.moves.length}</h2><button class="button primary" id="complete-review">Mark reviewed</button></div><div class="review-layout simple-review"><div><div class="review-board-with-eval"><div class="eval-column" role="img" aria-label="${esc(ev.description)}: ${ev.text}"><span class="eval-number">${ev.text}</span><div class="eval-track"><div class="eval-white" style="height:${ev.white}%"></div></div><small>White</small></div><div class="game-board">${boardHTML(c,{staticBoard:true,last:r})}</div></div><div class="row wrap section-space"><button class="button secondary" id="game-prev" ${gameStep===0?'disabled':''}>Previous move</button><button class="button primary" id="game-next" ${gameStep===g.moves.length?'disabled':''}>Next move</button></div></div></div></div>`
}
function cancelReviewAnalysis(){if(analysisBusy)reviewAttempts.delete(reviewGameIndex+':'+analysisStep);analysisToken++;analysisWorker?.terminate();analysisWorker=null;analysisBusy=false;analysisStep=0}
function startReviewAnalysis(gameIndex,step,chain=true,mode='quick'){
  const g=state.games?.[gameIndex],rows=g?moveNotes(g):[],row=rows[step-1];
  if(!g||!row||analysisBusy)return;
  const key=gameIndex+':'+step;
  reviewAttempts.add(key);analysisBusy=true;analysisStep=step;analysisMode=mode;
  const id=++analysisToken;
  analysisWorker=new Worker('opponent.js?v=20261114-29',{type:'module'});
  analysisWorker.onmessage=({data})=>{
    if(data.id!==analysisToken)return;
    analysisBusy=false;analysisWorker.terminate();analysisWorker=null;
    if(data.error)toast('Analysis could not finish. Try again.');
    else{g.analysis||=[];g.analysis[step-1]={...data,reviewQuality:mode,analyzedAt:Date.now()};save()}
    if(view==='games'&&reviewGameIndex===gameIndex)render();
    if(chain)queueReviewAnalysis(gameIndex);
  };
  analysisWorker.onerror=()=>{
    if(id!==analysisToken)return;
    analysisBusy=false;analysisWorker?.terminate();analysisWorker=null;
    toast('Analysis could not load. Try again.');
    if(view==='games'&&reviewGameIndex===gameIndex)render();
    if(chain)queueReviewAnalysis(gameIndex);
  };
  const moving=gameFrom(g,step).history({verbose:true}).at(-1);
  analysisWorker.postMessage({id,fen:row.fen,review:true,initialFen:g.fen,history:g.moves.slice(0,step),level:7,budget:mode==='deep'?3500:250});
  if(view==='games'&&reviewGameIndex===gameIndex)render();
}
function queueReviewAnalysis(gameIndex){
  const g=state.games?.[gameIndex];if(!g)return;
  const currentKey=gameIndex+':'+gameStep;
  if(currentKey!==reviewIdleKey){
    clearTimeout(reviewIdleTimer);reviewIdleKey=currentKey;
    if(analysisBusy&&analysisStep!==gameStep)cancelReviewAnalysis();
    if(gameStep>0){const targetStep=gameStep;reviewIdleTimer=setTimeout(()=>{
      if(view!=='games'||reviewGameIndex!==gameIndex||gameStep!==targetStep)return;
      const cached=g.analysis?.[targetStep-1];
      if(cached?.reviewVersion===3&&cached.reviewQuality==='deep')return;
      if(analysisBusy)cancelReviewAnalysis();
      startReviewAnalysis(gameIndex,targetStep,true,'deep');
    },750)}
  }
  if(analysisBusy)return;
  for(const step of [...new Set([gameStep,...Array.from({length:g.moves.length},(_,i)=>i+1)])].filter(n=>n>0)){
    const cached=g.analysis?.[step-1],key=gameIndex+':'+step;
    if(cached?.reviewVersion!==3&&!reviewAttempts.has(key)){startReviewAnalysis(gameIndex,step,true,'quick');return}
  }
}
function bindReview(){
  $$('[data-open-game]').forEach(b=>b.onclick=()=>{cancelReviewAnalysis();clearTimeout(reviewIdleTimer);reviewIdleKey='';reviewAttempts.clear();reviewGameIndex=Number(b.dataset.openGame);gameStep=0;go('games')});
  if($('#all-games'))$('#all-games').onclick=()=>{cancelReviewAnalysis();reviewGameIndex=null;render()};
  if($('#game-prev'))$('#game-prev').onclick=()=>{gameStep--;render()};
  if($('#game-next'))$('#game-next').onclick=()=>{gameStep++;render()};
  if($('#game-jump'))$('#game-jump').onchange=e=>{gameStep=Number(e.target.value);render()};
  if($('#complete-review'))$('#complete-review').onclick=()=>{state.checks[weekKey()]||={};state.checks[weekKey()].review=true;state.games[reviewGameIndex].reviewed=true;save();cancelReviewAnalysis();go('dashboard');toast('Game reviewed. Take one lesson into your next game.')};
  if($('#analyze-move'))$('#analyze-move').onclick=()=>{if(analysisBusy)return;startReviewAnalysis(reviewGameIndex,gameStep,false)};
  if(view==='games'&&reviewGameIndex!=null)queueReviewAnalysis(reviewGameIndex);
}
function trainingCoach(){if(!state.trainingCoach){const coaches=Object.values(state.coach||newCoach(currentRating()));state.trainingCoach={...coaches[0],target:Math.round(coaches.reduce((n,c)=>n+c.target,0)/coaches.length),fast:0,struggles:0,total:0,solved:0};state.trainingBaseline=state.trainingCoach.target}return state.trainingCoach}
function adjustChallenge(delta){const c=trainingCoach();const previous=state.active?.puzzle?puzzleMap.get(state.active.puzzle.id)?.rating:null;c.target=clamp((delta>0?Math.max(c.target,previous||0):Math.min(c.target,previous||c.target))+delta,400,2500);c.fast=0;c.struggles=0;c.reason='You adjusted the challenge. Automatic adjustment is still on.';state.challengeDirection=delta>0?'up':'down';if(state.active?.puzzle&&!state.active.puzzle.done&&!state.active.puzzle.moves.length&&!state.active.puzzle.mistakes.length&&!state.active.puzzle.hints){newPuzzle();}save();render();toast('Next fresh puzzle targets '+c.target+'. Automatic adjustment stays on.')}
function chooseTrainingPuzzle(skill){const c=trainingCoach(),fresh=bank.filter(p=>p.skill===skill&&!state.seen.includes(p.id)&&!state.seenPositions.includes(positionKey(p.fen)));const directed=state.challengeDirection==='up'?fresh.filter(p=>p.rating>=c.target):state.challengeDirection==='down'?fresh.filter(p=>p.rating<=c.target):fresh;return pickPuzzle(directed.length?directed:fresh,skill,c.target,[],[])}
function improvementHTML(){const c=trainingCoach(),results=state.sessions.filter(s=>s.version===2).flatMap(s=>s.results).concat(state.active?.results||[]),last=results.slice(-10),previous=results.slice(-20,-10),rate=a=>a.length?Math.round(a.filter(r=>r.clean).length/a.length*100):0;const rating=currentRating(),start=state.profile?.startRating,goal=state.profile?.goal||1500;return `<div class="panel section-space"><div class="row wrap"><h2>Your progress</h2><span class="badge">Automatic difficulty on</span></div><p><b>Puzzle target ${fmt(c.target)}</b> · ${c.target-(state.trainingBaseline||c.target)>=0?'+':''}${c.target-(state.trainingBaseline||c.target)} since tracking began</p><p class="fine">${last.length?`${rate(last)}% clean solves in your last ${last.length} puzzle${last.length===1?'':'s'}${previous.length?` · ${rate(last)-rate(previous)>=0?'+':''}${rate(last)-rate(previous)} percentage points versus the previous ${previous.length}`:''}.`:'Solve a few puzzles to start your trend.'} ${esc(c.reason)}</p>${rating!=null?`<div class="progress-track"><span style="width:${progressPercent()}%"></span></div><p class="fine">Game rating ${fmt(rating)} → goal ${fmt(goal)} · ${Math.max(0,goal-rating)} points to go${start!=null?` · ${rating-start>=0?'+':''}${rating-start} from your starting rating`:''}.</p>`:`<p class="fine">Goal: ${fmt(goal)} game rating. Add a game rating when you have one.</p>`}<p class="fine muted">Puzzle progress and computer results do not automatically change your game rating.</p></div>`}
if($('#global-settings'))$('#global-settings').onclick=openGameSettings;$$('nav button').forEach(b=>b.onclick=()=>go(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();go('dashboard')};$('#export').onclick=exportData;$('#import').onchange=importData;$('#cancel-promotion').onclick=()=>{pendingPromotion=null;$('#promotion').close()};document.addEventListener('visibilitychange',()=>{flushTime();lastTick=Date.now()});window.addEventListener('beforeunload',()=>{settleMatch();flushTime();save()});setInterval(()=>{if(view==='game'&&state.match?.clock&&!state.match.result&&!state.match.paused){if(settleClock(state.match)){stopEngine();recordGame();save();render()}else{const w=$('#white-clock'),b=$('#black-clock');if(w)w.textContent=clockDisplay(state.match.clock.w);if(b)b.textContent=clockDisplay(state.match.clock.b)}}if(view==='arena-live'&&arenaMatch&&!arenaMatch.paused&&!arenaMatch.result){if(tickArena())render();else{const w=$('#arena-white-clock'),b=$('#arena-black-clock');if(w)w.textContent=arenaMatch.clock?clockDisplay(arenaMatch.clock.w):'Untimed';if(b)b.textContent=arenaMatch.clock?clockDisplay(arenaMatch.clock.b):'Untimed'}}},50);setInterval(()=>{if(state.match&&!state.match.result&&!state.match.paused){const ended=settleMatch();if(!ended)save();if(view==='game'){if(ended)render();else{if($('#white-clock'))$('#white-clock').textContent=state.match.clock?clockDisplay(state.match.clock.w):'Untimed';if($('#black-clock'))$('#black-clock').textContent=state.match.clock?clockDisplay(state.match.clock.b):'Untimed'}}}flushTime();if($('#session-time')&&state.active)$('#session-time').textContent=duration(state.active.seconds);if($('#puzzle-time')&&state.active?.puzzle)$('#puzzle-time').textContent=relativeTime(state.active.puzzle.seconds)},1000);
try{const [p,l]=await Promise.all([fetch('puzzles.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('legacy-lessons.json').then(r=>r.json())]);bank=p;legacy=l;puzzleMap=new Map(bank.map(p=>[p.id,p]));if(state.coach&&!state.extraChallenge){for(const c of Object.values(state.coach))c.target=Math.min(2500,c.target+150);state.extraChallenge=true;save();}if(state.profile&&!state.coach)state.coach=newCoach(currentRating());if(state.coach&&!state.challengeUplift){for(const c of Object.values(state.coach)){c.target=Math.min(2500,c.target+250);c.reason='A higher starting challenge, as requested. Your results will guide the next steps.'}state.challengeUplift=true;save();}trainingCoach();if(state.match){state.match.level=Number(state.match.level)||2;state.match.turn=match().turn();settleMatch();}if(state.active&&!puzzleMap.has(state.active.puzzle?.id))state.active=null;render()}catch{$('#content').innerHTML='<div class="panel empty"><h1>Your training room couldn’t load.</h1><p>Check your connection and reload. Your saved records are still in this browser.</p><button class="button primary" id="reload-app">Reload training room</button></div>';$('#reload-app').onclick=()=>location.reload();}

function syncBoard(oldBoard,newBoard){for(const a of [...oldBoard.attributes])if(!newBoard.hasAttribute(a.name))oldBoard.removeAttribute(a.name);for(const a of newBoard.attributes)oldBoard.setAttribute(a.name,a.value);[...newBoard.children].forEach((fresh,i)=>{const old=oldBoard.children[i];for(const a of [...old.attributes])if(!fresh.hasAttribute(a.name))old.removeAttribute(a.name);for(const a of fresh.attributes)old.setAttribute(a.name,a.value);const oldImage=old.querySelector('img'),newImage=fresh.querySelector('img');if(oldImage&&newImage&&oldImage.getAttribute('src')===newImage.getAttribute('src')){for(const child of [...old.children])if(child!==oldImage)child.remove();for(const child of [...fresh.children])if(child!==newImage)old.append(child.cloneNode(true));}else old.innerHTML=fresh.innerHTML;});}
let dragGesture=null,suppressBoardClick=false,dragDropInProgress=false;
document.addEventListener('pointerdown',e=>{const square=e.target.closest('.square[data-square]');if(!square||e.button!==0||!square.querySelector('img'))return;const game=view==='game'&&state.match?match():view==='training'&&state.active?activeGame():null;if(!game)return;const color=view==='game'?'w':new Chess(puzzleMap.get(state.active.puzzle.id).fen).turn();if(game.get(square.dataset.square)?.color!==color)return;dragGesture={from:square.dataset.square,piece:game.get(square.dataset.square).type,x:e.clientX,y:e.clientY,board:square.closest('.board'),square,pointer:e.pointerId};square.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{const d=dragGesture;if(!d||d.pointer!==e.pointerId)return;if(!d.ghost&&Math.hypot(e.clientX-d.x,e.clientY-d.y)>6){d.ghost=d.square.querySelector('img').cloneNode();d.ghost.className='drag-piece';d.ghost.style.width=d.square.querySelector('img').getBoundingClientRect().width+'px';document.body.append(d.ghost);d.square.classList.add('drag-origin')}if(d.ghost){e.preventDefault();d.ghost.style.left=e.clientX+'px';d.ghost.style.top=e.clientY+'px';}},{passive:false});
function clearDrag(){const d=dragGesture;dragGesture=null;if(d){d.ghost?.remove();d.square.classList.remove('drag-origin');if(d.square.hasPointerCapture(d.pointer))d.square.releasePointerCapture(d.pointer)}return d;}
document.addEventListener('pointerup',e=>{if(!dragGesture||dragGesture.pointer!==e.pointerId)return;const d=clearDrag();if(!d?.ghost)return;suppressBoardClick=true;setTimeout(()=>suppressBoardClick=false,0);const destination=document.elementFromPoint(e.clientX,e.clientY)?.closest('.square[data-square]');if(!destination||destination.closest('.board')!==d.board||destination.dataset.square===d.from)return;dragDropInProgress=true;try{if(view==='game'){gameSelection=d.from;handleGameSquare(destination.dataset.square)}else{selectedSquare=d.from;destination.onclick?.();}}finally{dragDropInProgress=false}});
document.addEventListener('pointercancel',e=>{if(dragGesture?.pointer===e.pointerId)clearDrag()});document.addEventListener('lostpointercapture',e=>{if(dragGesture?.pointer===e.pointerId&&dragGesture.square===e.target)clearDrag()});document.addEventListener('click',e=>{if(suppressBoardClick&&e.target.closest('.board')){e.preventDefault();e.stopImmediatePropagation()}},true);
document.addEventListener('keydown',event=>{if(view!=='games'||reviewGameIndex==null||!['ArrowLeft','ArrowRight'].includes(event.key))return;const target=event.target;if(target?.matches?.('input,textarea,select,[contenteditable="true"]')||target?.isContentEditable)return;event.preventDefault();const total=state.games?.[reviewGameIndex]?.moves?.length||0;gameStep=clamp(gameStep+(event.key==='ArrowRight'?1:-1),0,total);render()});

// Animate only a single forward move on the same board position.
function boardSlide(oldBoard,newBoard){
 if (dragDropInProgress || !['game','arena-live','games'].includes(view) || !oldBoard.dataset.fen || oldBoard.dataset.fen!==newBoard.dataset.before || !newBoard.dataset.from || !newBoard.dataset.to) return null;
 return {from:newBoard.dataset.from,to:newBoard.dataset.to,flags:newBoard.dataset.flags};
}
function animateBoardSlide(board,move){
 if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
 const squares=[...board.children];
 const square=name=>squares.find(el=>el.getAttribute('aria-label')?.startsWith(name+','));
 const slide=(from,to)=>{const source=square(from),target=square(to),piece=target?.querySelector('.piece-img');if(!source||!target||!piece)return;const a=source.getBoundingClientRect(),b=target.getBoundingClientRect();target.style.zIndex='10';const animation=piece.animate([{transform:`translate(${a.left-b.left}px,${a.top-b.top}px)`},{transform:'translate(0,0)'}],{duration:120,easing:'ease-out'});animation.finished.then(()=>{target.style.zIndex=''},()=>{target.style.zIndex=''})};
 slide(move.from,move.to);
 if(move.flags?.includes('k'))slide('h'+move.from[1],'f'+move.from[1]);
 if(move.flags?.includes('q'))slide('a'+move.from[1],'d'+move.from[1]);
}

function settingsPicker(id,label,choices,current){return `<div class="settings-field"><span>${label}</span><div class="bot-picker"><select id="${id}" class="bot-picker-value" tabindex="-1" aria-hidden="true">${Object.entries(choices).map(([k,v])=>`<option value="${k}" ${k===current?'selected':''}>${v}</option>`).join('')}</select><details class="bot-picker-details"><summary aria-label="${label}"><span class="bot-picker-current"></span><span aria-hidden="true">⌄</span></summary><div class="bot-picker-list" aria-label="${label} options"></div></details></div></div>`}
function updateSettingsPreview(){const preview=$('#settings-preview');if(!preview)return;const chess=new Chess();preview.innerHTML=[...'87654321'].flatMap((r,ri)=>[...'abcdefgh'].map((f,fi)=>{const p=chess.get(f+r);const image=p?`<img src="pieces/${pieceTheme!=='classic'?pieceTheme+'/':''}${p.color}${p.type.toUpperCase()}.${pieceTheme==='castle'?'png':'svg'}?v=20261114-24" alt="">`:'';return `<span class="square ${(ri+fi)%2?'dark':''}">${image}</span>`})).join('')}
function openGameSettings(){
 const dialog=$('#game-settings-dialog');
 dialog.innerHTML=`<form method="dialog"><div class="settings-heading"><h2>Game settings</h2><button class="button secondary" value="close" aria-label="Close settings">✕</button></div><div class="settings-preview" id="settings-preview" role="img" aria-label="Preview of the selected board and pieces"></div>${settingsPicker('settings-board','Board color',boardThemes,boardTheme)}${settingsPicker('settings-pieces','Pieces',pieceThemes,pieceTheme)}<label class="settings-toggle"><input type="checkbox" id="settings-premoves" ${premovesEnabled?'checked':''}> <span>Enable premoves<small>Queue a move while the computer is thinking.</small></span></label><label class="settings-field" for="settings-puzzle-delay">Next puzzle delay: <span id="settings-puzzle-delay-value">${puzzleDelaySeconds} seconds</span><input type="range" id="settings-puzzle-delay" min="0" max="5" step="1" value="${puzzleDelaySeconds}"><small>0 seconds moves on immediately. Choose more time to review the puzzle.</small></label><button class="button primary" value="close">Done</button></form>`;
 $('#settings-board').onchange=e=>{boardTheme=e.target.value;document.body.dataset.boardTheme=boardTheme;try{localStorage.setItem('chess-board-theme',boardTheme)}catch{};updateSettingsPreview();render()};
 $('#settings-pieces').onchange=e=>{pieceTheme=e.target.value;try{localStorage.setItem('chess-piece-theme',pieceTheme)}catch{};updateSettingsPreview();render()};
 $('#settings-puzzle-delay').oninput=e=>{$('#settings-puzzle-delay-value').textContent=e.target.value+' seconds'};
 $('#settings-puzzle-delay').onchange=e=>{puzzleDelaySeconds=Number(e.target.value);try{localStorage.setItem('chess-puzzle-delay-seconds',String(puzzleDelaySeconds))}catch{};stopPuzzleAdvance();if(view==='training')render()};
 $('#settings-premoves').onchange=e=>{premovesEnabled=e.target.checked;try{localStorage.setItem('chess-premoves',premovesEnabled?'on':'off')}catch{};if(!premovesEnabled&&state.match){delete state.match.premove;gameSelection=null;save();render()}};
 updateSettingsPreview();bindBotPickers();dialog.showModal();
}

// Update the opponent's move without detaching the board that owns the pointer.
function renderGameDuringDrag(){
 const d=dragGesture,oldBoard=d?.board,room=$('.game-room');
 if(!d||!room||!oldBoard?.isConnected)return render();
 const held=match().get(d.from);
 if(!held||held.color!=='w'||held.type!==d.piece){clearDrag();gameSelection=null;toast('The computer captured that piece.');return render()}
 const template=document.createElement('template');template.innerHTML=gamePage();
 const fresh=template.content.querySelector('.game-room'),newBoard=fresh?.querySelector('.board');
 if(!fresh||!newBoard){clearDrag();return render()}
 const slide=boardSlide(oldBoard,newBoard);syncBoard(oldBoard,newBoard);
 if(d.ghost)d.square.classList.add('drag-origin');
 if(slide)animateBoardSlide(oldBoard,slide);
 for(const selector of ['.game-clocks','.game-status','.live-moves','.game-actions','.game-help']){const current=room.querySelector(selector),next=fresh.querySelector(selector);if(current&&next)current.replaceWith(next)}
 bindGame();gameSounds(state.match);
}

